Require an `Idempotency-Key` header from the client, add a unique column for it on `orders` (scoped by `account_id`, since keys are only unique per caller), and let the DB enforce it instead of a race-prone check-then-insert:

```sql
ALTER TABLE orders ADD COLUMN idempotency_key text;
CREATE UNIQUE INDEX orders_account_idem_key ON orders (account_id, idempotency_key);
```

```js
router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key");
  if (!key) return res.status(400).json({ error: "Idempotency-Key required" });
  try {
    const row = await db.write(
      "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) RETURNING *",
      [req.user.accountId, req.body.sku, req.body.quantity, key]
    );
    res.status(201).json(row);
  } catch (err) {
    if (err.code === "23505") { // unique_violation
      const existing = await db.query(
        "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
        [req.user.accountId, key]
      );
      return res.status(200).json(existing[0]);
    }
    throw err;
  }
});
```

The unique index is what actually prevents duplicates under concurrent retries; the app-level check alone would race.

